CREATE TEMPORARY VIEW fe_data_${grass_region_without_quote} AS
SELECT
    source1_request_id AS request_id
    ,case
        when source1_feature_detail='home-daily_discover-match_mix_feed_card' then 0
        else coalesce(
            if(operation = 'order' and click_spu_vsku_property.ctx_item_type = 2, cast(click_spu_vsku_property.spu_vsku_item_id as bigint), null)
            ,if(operation in ('cart', 'ppv') and spu_vsku_property.ctx_item_type = 2, cast(spu_vsku_property.spu_vsku_item_id as bigint), null)
            ,item_id)
     end as join_item_id
    ,case
        when source1_feature_detail='home-daily_discover-match_mix_feed_card' then source1_match_id
        when source1_feature_detail IN ('product-you_may_also_like-video', 'home-shopee_video-video_card', 'home-daily_discover-video') then source1_content_id
        else ''
    end as join_content_id
    ,case 
        when source1_feature_detail = 'product-you_may_also_like-item' then source1_item_unique_key
        when source1_page_type in ('global_search', 'search_prefill', 'search_in_pdp') then source1_item_unique_key
        else null 
    end as item_unique_key
    ,item_id
    ,shop_id
    ,device_id
    ,user_id
    ,source1_feature_detail AS feature_detail
    ,source1_target_type AS target_type
    ,event_timestamp
    ,log_timestamp
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation_cnt
    ,is_ads
    ,source1_location AS location
    ,session_id
    ,split(source1_queues, ',')[0] as queue
    ,split(source1_queues, ',') as queuelist
    ,page_type
    ,page_section
    ,platform
    ,event_id
    ,order_id
    ,keyword
    ,exp_group_ids
    ,ads_id as ads_id_fe
    ,source1_content_id AS content_id
    ,ctx_items

    ,grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,operation
FROM srdi_mart.dwd_sr_data_warehouse_platform
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date} and operation IN ('order','cart',' ppv')
AND coalesce(source1_request_id, '') != ''
AND item_id IS NOT NULL
AND nvl(source1_feature_detail, '') != '' AND source1_feature_detail != feature_detail

UNION ALL 

SELECT
    source2_request_id AS request_id
    ,case
       when source2_feature_detail='home-daily_discover-match_mix_feed_card' then 0 -- 依据实际情况进行转换，fashion card belog中是0，这里转为0
       else coalesce(
        if(operation = 'order' and click_spu_vsku_property.ctx_item_type = 2, cast(click_spu_vsku_property.spu_vsku_item_id as bigint), null)
        ,if(operation in ('cart', 'ppv') and spu_vsku_property.ctx_item_type = 2, cast(spu_vsku_property.spu_vsku_item_id as bigint), null)
        ,item_id)
     end as join_item_id
    ,case
        when source2_feature_detail='home-daily_discover-match_mix_feed_card' then source2_match_id
        when source2_feature_detail IN ('product-you_may_also_like-video', 'home-shopee_video-video_card', 'home-daily_discover-video') then source2_content_id
        else ''
    end as join_content_id
    ,case 
        when source2_feature_detail = 'product-you_may_also_like-item' then source2_item_unique_key
        when source2_page_type in ('global_search', 'search_prefill', 'search_in_pdp') then source2_item_unique_key
        else null 
    end as item_unique_key
    ,item_id
    ,shop_id
    ,device_id
    ,user_id
    ,source2_feature_detail AS feature_detail
    ,source2_target_type AS target_type
    ,event_timestamp
    ,log_timestamp
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation_cnt
    ,is_ads
    ,source2_location AS location
    ,session_id
    ,split(source2_queues, ',')[0] as queue
    ,split(source2_queues, ',') as queuelist
    ,page_type
    ,page_section
    ,platform
    ,event_id
    ,order_id
    ,keyword
    ,exp_group_ids
    ,ads_id as ads_id_fe
    ,source2_content_id AS content_id
    ,ctx_items

    ,grass_region
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,operation
FROM srdi_mart.dwd_sr_data_warehouse_platform
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date} and operation IN ('order','cart','ppv')
AND coalesce(source2_request_id, '') != ''
AND item_id IS NOT NULL
AND nvl(source2_feature_detail, '') != '' AND source2_feature_detail != source1_feature_detail AND source2_feature_detail != feature_detail
;
