INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_platform_fe_join_be_source
PARTITION (grass_region = ${grass_region},local_date = ${local_date},local_hour,regional_date,regional_hour,operation)
SELECT
     a.request_id
    ,a.item_id
    ,shop_id
    ,device_id
    ,user_id
    ,feature_detail
    ,target_type
    ,event_timestamp
    ,log_timestamp
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation_cnt
    ,if((tc_weight>=1.0001) or (tc_weight between 0.0001 and 0.9999) or (tc_weight<0),tc_rule_id,null) as tc_rule_id
    ,if((tc_weight>=1.0001) or (tc_weight between 0.0001 and 0.9999) or (tc_weight<0),tc_item_group_id,null) as tc_item_group_id
    ,ab_sign
    ,ads_id
    ,label_text
    ,label_name
    ,is_ads
    ,tc_boost_weight
    ,tc_rule_id as tc_rule_id_untreated
    ,tc_item_group_id as tc_item_group_id_untreated
    ,location
    ,server_log_tag
    ,smart_image_info
    ,session_id
    ,queue
    ,case when server_log_tag ='pdp' then ctx_items else null end as contextitems
    ,queuelist
    ,page_type
    ,page_section
    ,platform
    ,event_id
    ,order_id
    ,keyword
    ,exp_group_ids
    ,final_score
    ,ranker_id
    ,bundle
    ,rec_info_exp_list
    ,recall_info_list
    ,rank_score_named
    ,rerank_score_named
    ,subranker_id
    ,roughranker_id
    ,l1_cate_id
    ,l2_cate_id
    ,l3_cate_id
    ,price
    ,cart_score
    ,order_score
    ,click_score
    ,roughrank_score_named
    ,request_item_count
    ,item_group_types
    ,ranker_model_infos
    ,target_item_tags
    ,section_key_from_be
    ,data_type_from_be
    ,ads_extra_names
    ,ads_extra_values
    ,roi_item_type
    ,pmatch_score
    ,ecpm_weight
    ,ecpm_score
    ,mix_rank_info
    ,params_search_tag
    ,video_replace_info
    ,cali_scores_info
    ,ads_id_fe
    ,offset
    ,similar_product_replace_info
    ,replaced_item_id
    ,has_replacement_candidate
    ,eligible_to_replace
    ,cheapest_replacement
    ,recall_info_list_v2
    ,expansion_info

    ,local_hour
    ,regional_date
    ,regional_hour
    ,operation
from fe_data_${grass_region_without_quote} a
left join be_data_${grass_region_without_quote} b 
on a.request_id=b.request_id 
and a.join_item_id=b.item_id 
and a.join_content_id=b.join_content_id 
and (a.item_unique_key is null or a.item_unique_key=b.item_unique_key)
;
